  // a line without a Japanese recording plays its Korean one. The scene text (caption) stays Korean.
  const voiceLang=()=>{try{return localStorage.getItem("aftersignal:voice-lang")==="ko"?"ko":"ja"}catch{return "ja"}};
  const pick=entry=>entry&&voiceLang()==="ja"&&entry.ja?entry.ja:entry;
